DROP TABLE IF EXISTS `account`;
CREATE TABLE `account`  (
  `id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `type_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `currency_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `number` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `is_for_biz` tinyint(1) NOT NULL DEFAULT 0,
  `biz_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `biz_phone` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `biz_email` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `biz_website` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `biz_address` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `biz_description` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `is_partnership` tinyint(1) NOT NULL DEFAULT 0,
  `token` varchar(250) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '',
  `gateway_id` int(10) UNSIGNED NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `account_user_id_index`(`user_id`) USING BTREE,
  INDEX `account_type_id_index`(`type_id`) USING BTREE,
  INDEX `account_currency_id_index`(`currency_id`) USING BTREE,
  INDEX `account_gateway_id_index`(`gateway_id`) USING BTREE,
  CONSTRAINT `account_currency_id_foreign` FOREIGN KEY (`currency_id`) REFERENCES `accounts_currency` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `account_type_id_foreign` FOREIGN KEY (`type_id`) REFERENCES `accounts_type` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT,
  CONSTRAINT `account_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 188 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = DYNAMIC;

